// 1) Get user/body info from the Webhook node
const webhookItem = $items('Webhook')[0].json;
const body = webhookItem.body; // contains user_id, etc.

// 2) Get the model output from "Analyze an image"
const aiItem = $items('Analyze an image')[0].json;

// Gemini output: JSON is inside content.parts[0].text
const rawText = aiItem.content.parts[0].text;

// Remove ```json ... ``` wrapper
const jsonText = rawText
  .replace(/^```json\s*/m, '')
  .replace(/```$/m, '')
  .trim();

// Parse into object
const result = JSON.parse(jsonText);

// 3) Build the meal row (NO IMAGE URL HERE)
const mealRow = {
  user_id: body.user_id,
  eaten_at: new Date().toISOString().slice(0, 10), // YYYY-MM-DD
  calories_kcal: result.total_calories_kcal ?? null,
  protein_g: result.total_protein_g ?? null,
  carbs_g: result.total_carbs_g ?? null,
  fat_g: result.total_fat_g ?? null,
};

// 4) Return what DB needs + full breakdown for the app
return [
  {
    json: {
      meal: mealRow,       // Insert into Supabase
      breakdown: result,   // Show to user on analysis screen
    },
  },
];

// This node will output exactly the JSON we want to send to the app

